param([Parameter(Mandatory)][string]$ManagementUrl,[Parameter(Mandatory)][string]$OutputPath,[Parameter(Mandatory)][string]$SummaryPath,[Parameter(Mandatory)][string]$StopSignalPath,[int]$IntervalMilliseconds=1000,[int]$MaxDurationSeconds=300)
$ErrorActionPreference='Stop';New-Item -ItemType Directory -Force -Path (Split-Path $OutputPath),(Split-Path $SummaryPath)|Out-Null;$started=(Get-Date).ToUniversalTime().ToString('o');$failures=0;$samples=0;$stopObserved=$false;$status='COLLECTOR_MAX_DURATION_EXCEEDED';$deadline=(Get-Date).AddSeconds($MaxDurationSeconds)
try{while((Get-Date)-lt$deadline){$at=(Get-Date).ToUniversalTime().ToString('o');try{$snapshot=Invoke-RestMethod -Uri ($ManagementUrl.TrimEnd('/')+'/actuator/doengdiagnosticpool') -TimeoutSec 5;[ordered]@{timestamp=$at;poolMode=$snapshot.poolMode;providers=$snapshot.providers;metrics=$snapshot.metrics;failure=$null}|ConvertTo-Json -Depth 10 -Compress|Add-Content -LiteralPath $OutputPath -Encoding UTF8;$samples++}catch{$failures++;[ordered]@{timestamp=$at;poolMode=$null;providers=@();metrics=@();failure=$_.Exception.Message}|ConvertTo-Json -Depth 10 -Compress|Add-Content -LiteralPath $OutputPath -Encoding UTF8};if(Test-Path -LiteralPath $StopSignalPath){$stopObserved=$true;$status='COLLECTOR_STOPPED_BY_SIGNAL';break};Start-Sleep -Milliseconds $IntervalMilliseconds}}finally{$completed=(Get-Date).ToUniversalTime().ToString('o');[ordered]@{collectorStatus=$status;collectorProcessStartedAt=$started;collectorProcessCompletedAt=$completed;intervalMilliseconds=$IntervalMilliseconds;maxDurationSeconds=$MaxDurationSeconds;samples=$samples;failures=$failures;stopSignalObserved=$stopObserved}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $SummaryPath -Encoding UTF8};if(-not$stopObserved){exit 1}
